#!/usr/bin/env python3

import re
import shutil
import sys
import tempfile
from datetime import datetime
from pathlib import Path


# Default files, relative to the directory where you run the script.
DEFAULT_REPORT_PATH = Path("docs/q3_report.md")
DEFAULT_NOTES_PATH = Path("docs/meeting_notes_2026_09.txt")

INSERTION_MARKER = "[[INSERT_Q3_2026_REPORT_HERE]]"
START_MARKER = "----- BEGIN Q3 2026 BUSINESS REPORT -----"
END_MARKER = "----- END Q3 2026 BUSINESS REPORT -----"

REQUIRED_ATTRIBUTIONS = (
    "Rachel Kim",
    "Claire Fontaine",
)

TARGET_DATE_PATTERNS = (
    r"(?im)^(?:#+\s*)?September\s+8,\s+2026\b.*$",
    r"(?im)^(?:#+\s*)?Sep(?:tember)?\.?\s+8,\s+2026\b.*$",
    r"(?im)^(?:#+\s*)?2026[-/]09[-/]08\b.*$",
)

# Used to find the next date heading after September 8, thereby determining
# where the target section ends.
ANY_DATE_HEADING_PATTERN = re.compile(
    r"(?im)^(?:#+\s*)?(?:"
    r"(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|"
    r"Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|"
    r"Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)"
    r"\.?\s+\d{1,2},?\s+\d{4}"
    r"|"
    r"\d{4}[-/]\d{1,2}[-/]\d{1,2}"
    r")\b[^\r\n]*$"
)


def stop(message):
    raise RuntimeError(message)


def read_bytes_checked(path, description):
    if not path.exists():
        stop("{} does not exist: {}".format(description, path))

    if not path.is_file():
        stop("{} is not a regular file: {}".format(description, path))

    try:
        return path.read_bytes()
    except OSError as error:
        stop("Cannot read {} {}: {}".format(description, path, error))


def decode_utf8(raw, description):
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError as error:
        stop("{} must be UTF-8 text: {}".format(description, error))


def detect_newline(raw):
    """Choose the newline convention already used by the meeting notes."""
    crlf_count = raw.count(b"\r\n")
    lf_count = raw.count(b"\n") - crlf_count
    cr_count = raw.count(b"\r") - crlf_count

    if crlf_count >= lf_count and crlf_count >= cr_count and crlf_count > 0:
        return b"\r\n"

    if cr_count > lf_count and cr_count > 0:
        return b"\r"

    return b"\n"


def find_unique_target_heading(notes_text):
    """
    Find exactly one September 8, 2026 heading.

    Different accepted expressions can match the same heading, so results
    are deduplicated by their character offsets.
    """
    matches_by_span = {}

    for pattern in TARGET_DATE_PATTERNS:
        for match in re.finditer(pattern, notes_text):
            matches_by_span[(match.start(), match.end())] = match

    matches = list(matches_by_span.values())

    if len(matches) == 0:
        stop("No September 8, 2026 heading was found in the meeting notes.")

    if len(matches) != 1:
        matching_lines = [match.group(0) for match in matches]
        stop(
            "Expected one September 8, 2026 heading, but found {}: {!r}".format(
                len(matches),
                matching_lines,
            )
        )

    return matches[0]


def find_target_section(notes_text, target_heading):
    """
    Return the character range beginning at the September 8 heading and
    ending immediately before the next recognized date heading.
    """
    section_start = target_heading.start()
    section_end = len(notes_text)

    next_heading = ANY_DATE_HEADING_PATTERN.search(
        notes_text,
        target_heading.end(),
    )

    if next_heading is not None:
        section_end = next_heading.start()

    return section_start, section_end


def validate_report(report_raw):
    if len(report_raw) == 0:
        stop("The source report is empty.")

    report_text = decode_utf8(report_raw, "Source report")

    missing_names = [
        name
        for name in REQUIRED_ATTRIBUTIONS
        if name not in report_text
    ]

    if missing_names:
        stop(
            "The source report is missing required attribution(s): {}".format(
                ", ".join(missing_names)
            )
        )


def build_report_block(report_raw, newline):
    """
    Add report boundary markers while preserving the original report bytes.
    """
    block = START_MARKER.encode("utf-8") + newline
    block += report_raw

    if not report_raw.endswith((b"\n", b"\r")):
        block += newline

    block += END_MARKER.encode("utf-8")
    block += newline + newline

    return block


def make_backup_path(notes_path):
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    backup_path = notes_path.with_name(
        notes_path.name + ".backup_" + timestamp
    )

    if backup_path.exists():
        stop("Backup path unexpectedly already exists: {}".format(backup_path))

    return backup_path


def validate_original_notes(original_notes, report_raw):
    marker_raw = INSERTION_MARKER.encode("utf-8")
    start_raw = START_MARKER.encode("utf-8")
    end_raw = END_MARKER.encode("utf-8")

    marker_count = original_notes.count(marker_raw)

    if marker_count != 1:
        stop(
            "Expected insertion marker exactly once, but found {}. "
            "No changes were made.".format(marker_count)
        )

    if start_raw in original_notes or end_raw in original_notes:
        stop(
            "A Q3 2026 report boundary marker is already present. "
            "Refusing to insert a duplicate."
        )

    if report_raw in original_notes:
        stop(
            "The complete source report already occurs in the meeting notes. "
            "Refusing to insert a duplicate."
        )


def verify_candidate(
    original_notes,
    candidate,
    report_block,
    insertion_offset,
):
    marker_raw = INSERTION_MARKER.encode("utf-8")
    start_raw = START_MARKER.encode("utf-8")
    end_raw = END_MARKER.encode("utf-8")

    inserted_end = insertion_offset + len(report_block)

    if candidate[insertion_offset:inserted_end] != report_block:
        stop("Inserted report block does not match the expected bytes.")

    # Removing precisely the inserted bytes must recreate the original file.
    reconstructed_original = (
        candidate[:insertion_offset] + candidate[inserted_end:]
    )

    if reconstructed_original != original_notes:
        stop(
            "Preservation verification failed: pre-existing destination "
            "content would have changed."
        )

    if candidate.count(marker_raw) != 1:
        stop("The candidate does not contain exactly one insertion marker.")

    if candidate.count(start_raw) != 1:
        stop("The candidate does not contain exactly one report start marker.")

    if candidate.count(end_raw) != 1:
        stop("The candidate does not contain exactly one report end marker.")

    for name in REQUIRED_ATTRIBUTIONS:
        if name.encode("utf-8") not in report_block:
            stop(
                "Inserted block is missing required attribution: {}".format(
                    name
                )
            )


def insert_report(report_path, notes_path):
    report_raw = read_bytes_checked(report_path, "Source report")
    original_notes = read_bytes_checked(notes_path, "Meeting-notes file")

    validate_report(report_raw)
    validate_original_notes(original_notes, report_raw)

    notes_text = decode_utf8(original_notes, "Meeting-notes file")

    target_heading = find_unique_target_heading(notes_text)
    section_start, section_end = find_target_section(
        notes_text,
        target_heading,
    )

    marker_character_offset = notes_text.index(INSERTION_MARKER)

    if not (
        section_start
        <= marker_character_offset
        < section_end
    ):
        stop(
            "The insertion marker is not inside the September 8, 2026 "
            "section. No changes were made."
        )

    marker_raw = INSERTION_MARKER.encode("utf-8")
    marker_byte_offset = original_notes.index(marker_raw)

    newline = detect_newline(original_notes)
    report_block = build_report_block(report_raw, newline)

    # Insert immediately before the placeholder. The placeholder and every
    # other original byte remain in place.
    candidate = (
        original_notes[:marker_byte_offset]
        + report_block
        + original_notes[marker_byte_offset:]
    )

    verify_candidate(
        original_notes,
        candidate,
        report_block,
        marker_byte_offset,
    )

    backup_path = make_backup_path(notes_path)

    try:
        shutil.copy2(str(notes_path), str(backup_path))
    except OSError as error:
        stop("Could not create backup {}: {}".format(backup_path, error))

    temporary_path = None

    try:
        with tempfile.NamedTemporaryFile(
            mode="wb",
            prefix="." + notes_path.name + ".",
            suffix=".tmp",
            dir=str(notes_path.parent),
            delete=False,
        ) as temporary_file:
            temporary_path = Path(temporary_file.name)
            temporary_file.write(candidate)
            temporary_file.flush()

        if temporary_path.read_bytes() != candidate:
            stop("Temporary-file verification failed.")

        # Atomic on the normal case where the temporary and destination files
        # are on the same filesystem.
        temporary_path.replace(notes_path)
        temporary_path = None

        written_notes = notes_path.read_bytes()

        if written_notes != candidate:
            stop(
                "Post-write verification failed. Restore the original from: "
                + str(backup_path)
            )

    except Exception:
        if temporary_path is not None and temporary_path.exists():
            try:
                temporary_path.unlink()
            except OSError:
                pass
        raise

    return backup_path, len(report_block)


def main():
    if len(sys.argv) > 3:
        print(
            "Usage: python insert_q3_report.py "
            "[REPORT_PATH] [MEETING_NOTES_PATH]",
            file=sys.stderr,
        )
        return 2

    if len(sys.argv) >= 2:
        report_path = Path(sys.argv[1])
    else:
        report_path = DEFAULT_REPORT_PATH

    if len(sys.argv) >= 3:
        notes_path = Path(sys.argv[2])
    else:
        notes_path = DEFAULT_NOTES_PATH

    try:
        backup_path, inserted_byte_count = insert_report(
            report_path,
            notes_path,
        )
    except Exception as error:
        print("ERROR: {}".format(error), file=sys.stderr)
        return 1

    print("SUCCESS: Q3 2026 business report inserted.")
    print("Destination: {}".format(notes_path))
    print("Backup: {}".format(backup_path))
    print("Inserted bytes: {}".format(inserted_byte_count))
    print("VERIFIED: No pre-existing destination bytes were removed.")
    print(
        "VERIFIED: The report has both required attributions and "
        "the insertion marker remains in place."
    )

    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3

import re
import shutil
import sys
import tempfile
from datetime import datetime
from pathlib import Path


DEFAULT_REPORT = Path("docs/q3_report.md")
DEFAULT_NOTES = Path("docs/meeting_notes_2026_09.txt")

INSERTION_MARKER = "[[INSERT_Q3_2026_REPORT_HERE]]"
START_MARKER = "----- BEGIN Q3 2026 BUSINESS REPORT -----"
END_MARKER = "----- END Q3 2026 BUSINESS REPORT -----"

REQUIRED_NAMES = ("Rachel Kim", "Claire Fontaine")

TARGET_DATE_PATTERNS = (
    r"(?im)^(?:#+\s*)?September\s+8,\s+2026\b.*$",
    r"(?im)^(?:#+\s*)?Sep(?:tember)?\.?\s+8,\s+2026\b.*$",
    r"(?im)^(?:#+\s*)?2026[-/]09[-/]08\b.*$",
)

# Recognizes the next date heading, which marks the end of the target section.
ANY_DATE_HEADING = re.compile(
    r"(?im)^(?:#+\s*)?(?:"
    r"(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|"
    r"Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|"
    r"Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)"
    r"\.?\s+\d{1,2},?\s+\d{4}"
    r"|"
    r"\d{4}[-/]\d{1,2}[-/]\d{1,2}"
    r")\b[^\r\n]*$"
)


def fail(message):
    raise RuntimeError(message)


def read_file(path, label):
    if not path.is_file():
        fail("{} does not exist or is not a file: {}".format(label, path))

    try:
        return path.read_bytes()
    except OSError as error:
        fail("Unable to read {}: {}".format(label, error))


def decode_utf8(content, label):
    try:
        return content.decode("utf-8")
    except UnicodeDecodeError as error:
        fail("{} is not valid UTF-8: {}".format(label, error))


def detect_newline(content):
    crlf = content.count(b"\r\n")
    lf = content.count(b"\n") - crlf
    cr = content.count(b"\r") - crlf

    if crlf and crlf >= lf and crlf >= cr:
        return b"\r\n"

    if cr and cr > lf:
        return b"\r"

    return b"\n"


def find_target_heading(notes_text):
    # Multiple accepted patterns may identify the same heading. Deduplicate
    # matches using their character positions.
    matches = {}

    for pattern in TARGET_DATE_PATTERNS:
        for match in re.finditer(pattern, notes_text):
            matches[(match.start(), match.end())] = match

    unique_matches = list(matches.values())

    if not unique_matches:
        fail("No September 8, 2026 heading was found.")

    if len(unique_matches) != 1:
        headings = [match.group(0) for match in unique_matches]
        fail(
            "Expected exactly one September 8, 2026 heading; found {}: {!r}"
            .format(len(unique_matches), headings)
        )

    return unique_matches[0]


def find_target_section(notes_text, target_heading):
    section_start = target_heading.start()
    section_end = len(notes_text)

    next_heading = ANY_DATE_HEADING.search(
        notes_text,
        target_heading.end(),
    )

    if next_heading is not None:
        section_end = next_heading.start()

    return section_start, section_end


def validate_inputs(report, notes):
    if not report:
        fail("The Q3 report is empty.")

    report_text = decode_utf8(report, "Q3 report")

    missing = [name for name in REQUIRED_NAMES if name not in report_text]

    if missing:
        fail(
            "The Q3 report is missing required attribution(s): "
            + ", ".join(missing)
        )

    marker = INSERTION_MARKER.encode("utf-8")
    start = START_MARKER.encode("utf-8")
    end = END_MARKER.encode("utf-8")

    marker_count = notes.count(marker)

    if marker_count != 1:
        fail(
            "Expected the insertion marker exactly once; found {}."
            .format(marker_count)
        )

    if start in notes or end in notes:
        fail(
            "Report boundary markers already exist in the meeting notes. "
            "Refusing to insert a duplicate."
        )

    if report in notes:
        fail(
            "The complete report already exists in the meeting notes. "
            "Refusing to insert a duplicate."
        )


def build_report_block(report, newline):
    block = START_MARKER.encode("utf-8") + newline
    block += report

    if not report.endswith((b"\n", b"\r")):
        block += newline

    block += END_MARKER.encode("utf-8")
    block += newline + newline

    return block


def make_backup_path(notes_path):
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    backup = notes_path.with_name(
        notes_path.name + ".backup_" + timestamp
    )

    if backup.exists():
        fail("Backup already exists unexpectedly: {}".format(backup))

    return backup


def verify_candidate(original, candidate, block, offset):
    block_end = offset + len(block)

    # The inserted range must be exactly the expected report block.
    if candidate[offset:block_end] != block:
        fail("Inserted report block failed byte-for-byte verification.")

    # Removing only the inserted range must reproduce the original notes.
    reconstructed = candidate[:offset] + candidate[block_end:]

    if reconstructed != original:
        fail("Existing meeting-note content would not be preserved.")

    expected_counts = (
        (INSERTION_MARKER.encode("utf-8"), 1, "insertion marker"),
        (START_MARKER.encode("utf-8"), 1, "start marker"),
        (END_MARKER.encode("utf-8"), 1, "end marker"),
    )

    for value, expected, label in expected_counts:
        actual = candidate.count(value)

        if actual != expected:
            fail(
                "Expected {} {} occurrence(s); found {}."
                .format(expected, label, actual)
            )

    for name in REQUIRED_NAMES:
        if name.encode("utf-8") not in block:
            fail("Inserted report is missing attribution: " + name)


def write_atomically(notes_path, candidate, backup_path):
    try:
        shutil.copy2(str(notes_path), str(backup_path))
    except OSError as error:
        fail("Unable to create backup: {}".format(error))

    temporary_path = None

    try:
        with tempfile.NamedTemporaryFile(
            mode="wb",
            prefix="." + notes_path.name + ".",
            suffix=".tmp",
            dir=str(notes_path.parent),
            delete=False,
        ) as temporary:
            temporary_path = Path(temporary.name)
            temporary.write(candidate)
            temporary.flush()

        if temporary_path.read_bytes() != candidate:
            fail("Temporary-file verification failed.")

        temporary_path.replace(notes_path)
        temporary_path = None

        if notes_path.read_bytes() != candidate:
            fail(
                "Post-write verification failed. Restore the backup: {}"
                .format(backup_path)
            )

    except Exception:
        if temporary_path is not None and temporary_path.exists():
            try:
                temporary_path.unlink()
            except OSError:
                pass
        raise


def insert_report(report_path, notes_path):
    report = read_file(report_path, "Q3 report")
    original_notes = read_file(notes_path, "Meeting notes")

    validate_inputs(report, original_notes)

    notes_text = decode_utf8(original_notes, "Meeting notes")
    target_heading = find_target_heading(notes_text)

    section_start, section_end = find_target_section(
        notes_text,
        target_heading,
    )

    marker_character_offset = notes_text.index(INSERTION_MARKER)

    if not section_start <= marker_character_offset < section_end:
        fail(
            "The insertion marker is not in the September 8, 2026 section."
        )

    marker_bytes = INSERTION_MARKER.encode("utf-8")
    marker_byte_offset = original_notes.index(marker_bytes)

    newline = detect_newline(original_notes)
    block = build_report_block(report, newline)

    # Insert before the marker without removing or replacing original bytes.
    candidate = (
        original_notes[:marker_byte_offset]
        + block
        + original_notes[marker_byte_offset:]
    )

    verify_candidate(
        original_notes,
        candidate,
        block,
        marker_byte_offset,
    )

    backup_path = make_backup_path(notes_path)
    write_atomically(notes_path, candidate, backup_path)

    return backup_path, len(block)


def main():
    if len(sys.argv) > 3:
        print(
            "Usage: python insert_q3_report.py "
            "[REPORT_FILE] [MEETING_NOTES_FILE]",
            file=sys.stderr,
        )
        return 2

    report_path = (
        Path(sys.argv[1]) if len(sys.argv) >= 2 else DEFAULT_REPORT
    )
    notes_path = (
        Path(sys.argv[2]) if len(sys.argv) >= 3 else DEFAULT_NOTES
    )

    try:
        backup_path, inserted_bytes = insert_report(
            report_path,
            notes_path,
        )
    except Exception as error:
        print("ERROR: {}".format(error), file=sys.stderr)
        return 1

    print("SUCCESS: Q3 2026 business report inserted.")
    print("Destination: {}".format(notes_path))
    print("Backup: {}".format(backup_path))
    print("Inserted bytes: {}".format(inserted_bytes))
    print("VERIFIED: Existing meeting-note content was preserved.")
    print(
        "VERIFIED: Both required attributions are present and "
        "the insertion marker remains."
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
